201			return runWith(t, fakeEnv{roots: roots, handshake: handshakeReturning(state), route: route}, target())
202		}
203		noRoute := withRoute(func(context.Context, net.IP) (RouteHop, error) {
204			return RouteHop{}, nettrace.ErrNoRoute
205		})
206		okRoute := withRoute(func(context.Context, net.IP) (RouteHop, error) {
207			return RouteHop{}, nil
208		})
209	
210		if got := verdictOf(t, noRoute, CheckRoute); got != Fail {
211			t.Fatalf("route verdict = %v, want Fail", got)
212		}
213		for _, id := range []CheckID{CheckICMP, CheckTCP, CheckTLSHandshake, CheckHTTP} {
214			c := checkNamed(t, noRoute, id)
215			if c.Verdict == NotApplicable || c.Because != "" {
216				t.Errorf("%s = %v because %q, want it probed, not blocked", id, c.Verdict, c.Because)
217			}
218			if want := verdictOf(t, okRoute, id); c.Verdict != want {
219				t.Errorf("%s = %v with no route, %v with a route; want the same", id, c.Verdict, want)
220			}
221		}
222		if got := Summarize(noRoute); got != Fail {
223			t.Fatalf("Summarize = %v, want Fail", got)
224		}
225	}
