350	// TestRunStepWalksTheSamePipelineAsRun pins the factoring: Run and RunStep share
351	// runStage, so the skip rule cannot mean one thing to a batch caller and another
352	// to a view chaining the stages through messages.
353	func TestRunStepWalksTheSamePipelineAsRun(t *testing.T) {
354		env := fakeEnv{
355			dial: func(context.Context, string) (time.Duration, error) {
356				return 0, errors.New("connection refused")
357			},
358		}
359	
360		whole, err := Run(context.Background(), target(), env, DefaultSettings())
361		if err != nil {
362			t.Fatalf("Run: %v", err)
363		}
364	
365		var piecewise Results
366		for _, id := range Steps() {
367			piecewise = RunStep(context.Background(), target(), env, DefaultSettings(), id, piecewise)
368		}
369	
370		if len(piecewise.All()) != len(whole.All()) {
371			t.Fatalf("piecewise produced %d checks, Run produced %d", len(piecewise.All()), len(whole.All()))
372		}
373		for i, c := range whole.All() {
374			got := piecewise.All()[i]
375			if got.ID != c.ID || got.Verdict != c.Verdict || got.Because != c.Because {
376				t.Errorf("check %d: piecewise %s/%s/%s, Run %s/%s/%s",
377					i, got.ID, got.Verdict, got.Because, c.ID, c.Verdict, c.Because)
378			}
379		}
380	}
