382	// TestRunStepDoesNotWriteIntoTheResultsItWasGiven is the property a Bubble Tea
383	// caller depends on: the previous value is held by the model while the next
384	// stage runs on a goroutine, so a shared backing array would be a data race on
385	// the one thing Rule 110 exists to prevent.
386	func TestRunStepDoesNotWriteIntoTheResultsItWasGiven(t *testing.T) {
387		first := RunStep(context.Background(), target(), fakeEnv{}, DefaultSettings(), StageResolve, Results{})
388		snapshot := len(first.All())
389	
390		RunStep(context.Background(), target(), fakeEnv{}, DefaultSettings(), StageReach, first)
391		RunStep(context.Background(), target(), fakeEnv{}, DefaultSettings(), StageConnect, first)
392	
393		if len(first.All()) != snapshot {
394			t.Fatalf("the earlier Results grew from %d to %d checks", snapshot, len(first.All()))
395		}
396	}
