160	// produced runs the battery and returns every check it observed.
161	func produced(t *testing.T) []Check {
162		t.Helper()
163		var all []Check
164		for _, s := range batteries(t) {
165			res, err := Run(context.Background(), s.tg, s.env, DefaultSettings())
166			if err != nil {
167				t.Fatalf("%s: %v", s.name, err)
168			}
169			all = append(all, res.All()...)
170		}
171		return all
172	}
