174	// TestEveryCheckAScenarioProducesIsExplained is the contract: no state a user
175	// can reach leaves them reading a verdict with nothing telling them what it
176	// means. It is behavioural rather than a list of pairs, because a list would
177	// have to be kept in step with the stages by hand.
178	func TestEveryCheckAScenarioProducesIsExplained(t *testing.T) {
179		for _, s := range batteries(t) {
180			res, err := Run(context.Background(), s.tg, s.env, DefaultSettings())
181			if err != nil {
182				t.Fatalf("%s: %v", s.name, err)
183			}
184			for _, c := range res.All() {
185				e := Explain(c)
186				if strings.Contains(e.Means, "No guidance is written") {
187					t.Errorf("%s: %s at %s (reason %q) fell through to the fallback",
188						s.name, c.ID, c.Verdict, c.Reason)
189				}
190				if strings.TrimSpace(e.Means) == "" {
191					t.Errorf("%s: %s at %s has no explanation", s.name, c.ID, c.Verdict)
192				}
193				if e.Observed != c.Summary {
194					t.Errorf("%s: %s restates the observation instead of carrying it", s.name, c.ID)
195				}
196			}
197		}
198	}
