200	// TestNoGuidanceRowIsUnreachable catches the other drift: a row written for a
201	// combination no stage produces. It is dead text that reads as coverage.
202	func TestNoGuidanceRowIsUnreachable(t *testing.T) {
203		type key struct {
204			id     CheckID
205			v      Verdict
206			reason Reason
207		}
208		seen := map[key]bool{}
209		for _, c := range produced(t) {
210			seen[key{c.ID, c.Verdict, c.Reason}] = true
211		}
212	
213		for _, g := range explanations {
214			if g.reason != "" {
215				if !seen[key{g.check, g.verdict, g.reason}] {
216					t.Errorf("guidance for %s/%s/%s is unreachable — no scenario produces it",
217						g.check, g.verdict, g.reason)
218				}
219				continue
220			}
221			// A reason-less row is reached by any reason for that verdict.
222			found := false
223			for k := range seen {
224				if k.id == g.check && k.v == g.verdict {
225					found = true
226				}
227			}
228			if !found {
229				t.Errorf("guidance for %s/%s is unreachable — no scenario produces it", g.check, g.verdict)
230			}
231		}
232	}
