302	// that deserves more than the generic line, because a user who expected TLS
303	// there needs to know the port answered.
304	func TestANonTlsPortIsExplainedAsNormal(t *testing.T) {
305		e := Explain(Check{ID: CheckTLSHandshake, Verdict: NotApplicable, Reason: ReasonNotTLS})
306		if !strings.Contains(strings.ToLower(e.Means), "not with tls") {
307			t.Errorf("means %q does not say the port answered with something else", e.Means)
308		}
309		if e.Do == "" {
310			t.Error("a port that does not speak TLS when one was expected deserves a next step")
311		}
312	}
313	
314	// TestNoTwoRowsShareTheirText catches the copy-paste that makes a table look
315	// complete while saying the same thing everywhere.
316	func TestNoTwoRowsShareTheirText(t *testing.T) {
317		seen := map[string]string{}
318		for _, g := range explanations {
319			key := string(g.check) + "/" + g.verdict.String() + "/" + string(g.reason)
320			if prev, ok := seen[g.means]; ok {
321				t.Errorf("%s repeats the explanation of %s", key, prev)
322			}
323			seen[g.means] = key
324			if len(g.means) < 40 {
325				t.Errorf("%s explains in %d characters, which is a restatement rather than a meaning",
326					key, len(g.means))
327			}
328		}
329	}
