15	func runWith(t *testing.T, env Env, tg Target) []Check {
16		t.Helper()
17		res, err := Run(context.Background(), tg, env, DefaultSettings())
18		if err != nil {
19			t.Fatalf("Run: %v", err)
20		}
21		return res.All()
