26	// TestUnknownIsTheZeroVerdict states structurally what SecretVerdict's *bool
27	// states elsewhere: a check nobody filled in must not read as a pass.
28	func TestUnknownIsTheZeroVerdict(t *testing.T) {
29		var v Verdict
30		if v != Unknown {
31			t.Fatalf("zero Verdict is %v, want Unknown — a check nobody answered must not read as OK", v)
32		}
33		var c Check
34		if c.Verdict != Unknown {
35			t.Fatalf("zero Check.Verdict is %v, want Unknown", c.Verdict)
36		}
37	}
