77	// TestEveryCheckHasATitleAndAStage catches drift in both directions: a check
78	// that no stage produces, and a check no title names.
79	func TestEveryCheckHasATitleAndAStage(t *testing.T) {
80		produced := map[CheckID]bool{}
81		for _, s := range stages() {
82			for _, id := range s.produces {
83				if produced[id] {
84					t.Fatalf("check %q is produced by more than one stage", id)
85				}
86				produced[id] = true
87				if checkTitles[id] == "" {
88					t.Errorf("check %q has no title", id)
89				}
90			}
91		}
92		for id := range checkTitles {
93			if !produced[id] {
94				t.Errorf("check %q has a title but no stage produces it", id)
95			}
96		}
97	}
