99	// TestAGateBelongsToTheStageThatProducesIt stops a dependency pointing at a
100	// check the named stage never emits — the cascade would then never fire.
101	func TestAGateBelongsToTheStageThatProducesIt(t *testing.T) {
102		for _, s := range stages() {
103			if s.gate == "" {
104				continue
105			}
106			found := false
107			for _, id := range s.produces {
108				if id == s.gate {
109					found = true
110				}
111			}
112			if !found {
113				t.Errorf("stage %q gates on %q, which it does not produce", s.id, s.gate)
114			}
115		}
116	}
