120	func TestAFailedResolutionBlocksEverythingBelowItAndNamesItself(t *testing.T) {
121		checks := runWith(t, fakeEnv{
122			resolve: func(context.Context, string, string) ([]net.IP, error) {
123				return nil, errors.New("no such host")
124			},
125		}, target())
126	
127		if got := verdictOf(t, checks, CheckResolve); got != Fail {
128			t.Fatalf("resolve verdict = %v, want Fail", got)
129		}
130		for _, id := range []CheckID{CheckTCP, CheckTLSChain, CheckHTTP} {
131			c := checkNamed(t, checks, id)
132			if c.Verdict != NotApplicable {
