279	func TestSummarizeIsTheOnlyAggregate(t *testing.T) {
280		for _, tc := range []struct {
281			name string
282			in   []Verdict
283			want Verdict
284		}{
285			{"all ok", []Verdict{OK, OK}, OK},
286			{"a warning shows", []Verdict{OK, Warn}, Warn},
287			{"a failure outranks a warning", []Verdict{Warn, Fail, OK}, Fail},
288			{"unknown outranks a warning", []Verdict{Warn, Unknown}, Unknown},
289			{"a failure outranks unknown", []Verdict{Unknown, Fail}, Fail},
290			{"not-applicable never colours the headline", []Verdict{OK, NotApplicable}, OK},
291			{"nothing but not-applicable is unknown", []Verdict{NotApplicable, NotApplicable}, Unknown},
292			{"no checks at all is unknown", nil, Unknown},
293			// Info is an observation with no objective, so like NotApplicable it
294			// never colours the headline and never counts as having looked.
295			{"info never colours the headline", []Verdict{OK, Info}, OK},
296			{"info does not hide a warning", []Verdict{Warn, Info}, Warn},
297			{"info does not hide a failure", []Verdict{Info, Fail}, Fail},
298			{"info does not hide unknown", []Verdict{Info, Unknown}, Unknown},
299			{"nothing but info and not-applicable is unknown", []Verdict{Info, NotApplicable}, Unknown},
300			{"nothing but info is unknown", []Verdict{Info, Info}, Unknown},
301		} {
302			t.Run(tc.name, func(t *testing.T) {
303				checks := make([]Check, 0, len(tc.in))
304				for _, v := range tc.in {
305					checks = append(checks, Check{Verdict: v})
306				}
307				if got := Summarize(checks); got != tc.want {
308					t.Fatalf("Summarize = %v, want %v", got, tc.want)
309				}
310			})
311		}
312	}
