398	// TestEveryStageIsNamedForAProgressLine — a stage the user waits on with no
399	// label is the mute spinner this indirection exists to avoid.
400	func TestEveryStageIsNamedForAProgressLine(t *testing.T) {
401		for _, id := range Steps() {
402			if StageTitle(id) == "" {
403				t.Errorf("stage %q has no title", id)
404			}
405		}
406		if len(Steps()) != len(stages()) {
407			t.Errorf("Steps() reports %d stages, the pipeline has %d", len(Steps()), len(stages()))
408		}
