1	package netcheck
2	
3	import (
4		"context"
5		"crypto/tls"
6		"crypto/x509"
7		"errors"
8		"net"
9		"strings"
10		"testing"
11		"time"
12	
13		"github.com/anthnel/devdesk/internal/nettrace"
14	)
15	
16	// scenario is one situation the battery drives through Run. Between them they
17	// have to produce every row of the guidance table — which is what
18	// TestNoGuidanceRowIsUnreachable checks, so a row written for a state that
19	// cannot happen fails the build rather than sitting there looking helpful.
20	type scenario struct {
21		name string
22		env  Env
23		tg   Target
24	}
25	
26	func batteries(t *testing.T) []scenario {
27		t.Helper()
28	
29		good, goodRoots := buildChain(t, chainOpts{dnsNames: []string{"example.com"}, withIntermediate: true})
30		leafOnly, leafRoots := buildChain(t, chainOpts{dnsNames: []string{"example.com"}})
31		incomplete, incRoots := buildChain(t, chainOpts{
32			dnsNames: []string{"example.com"}, withIntermediate: true, omitIntermediate: true})
33		selfSigned, _ := buildChain(t, chainOpts{dnsNames: []string{"example.com"}, selfSigned: true})
34		wrongName, wrongRoots := buildChain(t, chainOpts{dnsNames: []string{"other.test"}, withIntermediate: true})
35		old, oldRoots := buildChain(t, chainOpts{
36			dnsNames: []string{"example.com"}, withIntermediate: true, version: tls.VersionTLS10})
37		soon, soonRoots := buildChain(t, chainOpts{
38			dnsNames: []string{"example.com"}, withIntermediate: true, notAfter: testNow.Add(9 * 24 * time.Hour)})
39		expired, expRoots := buildChain(t, chainOpts{
40			dnsNames: []string{"example.com"}, notAfter: testNow.Add(-3 * 24 * time.Hour)})
41		future, futureRoots := buildChain(t, chainOpts{
42			dnsNames:  []string{"example.com"},
43			notBefore: testNow.Add(48 * time.Hour), notAfter: testNow.Add(400 * 24 * time.Hour)})
44		onIP, ipRoots := buildChain(t, chainOpts{
45			ips: []net.IP{net.ParseIP("10.2.3.4")}, withIntermediate: true})
46	
47		ip := Target{Host: "10.2.3.4", Port: 443}
48	
49		return []scenario{
50			{"everything sound", fakeEnv{roots: goodRoots, handshake: handshakeReturning(good)}, target()},
51			{"chain verifies but no intermediates were sent",
52				fakeEnv{roots: leafRoots, handshake: handshakeReturning(leafOnly)}, target()},
53			{"incomplete chain",
54				fakeEnv{roots: incRoots, handshake: handshakeReturning(incomplete)}, target()},
55			{"self-signed",
56				fakeEnv{roots: x509.NewCertPool(), handshake: handshakeReturning(selfSigned)}, target()},
57			{"untrusted root",
58				fakeEnv{roots: x509.NewCertPool(), handshake: handshakeReturning(good)}, target()},
59			{"wrong hostname",
60				fakeEnv{roots: wrongRoots, handshake: handshakeReturning(wrongName)}, target()},
61			{"deprecated protocol version",
62				fakeEnv{roots: oldRoots, handshake: handshakeReturning(old)}, target()},
63			{"expiring soon",
64				fakeEnv{roots: soonRoots, handshake: handshakeReturning(soon)}, target()},
65			{"expired",
66				fakeEnv{roots: expRoots, handshake: handshakeReturning(expired)}, target()},
67			{"not yet valid",
68				fakeEnv{roots: futureRoots, handshake: handshakeReturning(future)}, target()},
69	
70			{"the name does not resolve", fakeEnv{
71				resolve: func(context.Context, string, string) ([]net.IP, error) {
72					return nil, errors.New("no such host")
73				}}, target()},
74			{"the resolver answers with something unusable", fakeEnv{
75				resolve: func(context.Context, string, string) ([]net.IP, error) {
76					return nil, &net.DNSError{Err: "server misbehaving", Name: "example.com", IsTemporary: true}
77				}}, target()},
78			{"a literal address with a reverse record", fakeEnv{
79				roots: ipRoots, handshake: handshakeReturning(onIP),
80				reverse: func(context.Context, string, string) ([]string, error) {
81					return []string{"host.corp.internal."}, nil
82				}}, ip},
83			{"a literal address without a reverse record",
84				fakeEnv{roots: ipRoots, handshake: handshakeReturning(onIP)}, ip},
85	
86			{"echo is filtered", fakeEnv{
87				roots: goodRoots, handshake: handshakeReturning(good),
88				ping: func(_ context.Context, _ string, n int) (PingStats, error) {
89					return PingStats{Sent: n}, nil
90				}}, target()},
