	switch id {
	case netcheck.CheckResolve:
		return "DNS resolution"
	case netcheck.CheckTCP:
		return "TCP connect"
	case netcheck.CheckICMP:
		return "ICMP echo"
	case netcheck.CheckTLSChain:
		return "Certificate chain"
	default:

	out := m.Render()
