	steps := netcheck.Steps()

	for i := 0; i < len(steps)-1; i++ {
		next, cmd := step(t, m, stageDoneMsg{
			gen: m.runGen, stage: steps[i], next: i + 1, results: netcheck.ResultsOf(),
